import{_ as e,o as a,c as s}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"proxy Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"proxy","tag":"proxy","title":"proxy Tag","prev":null,"next":null,"posts":[{"title":"Archlinux下终端进行代理的解决方案","url":"/posts/2013-07-18-archlinux-terminal-proxy/","date":"2013-07-18 22:05","tags":["linux","proxy"],"html":"<p>Linux 下软件安装基本都是在终端下进行的....<br>\\n虽说安装软件基本上选对源就没有无法安装的,但是 Archlinux 下的 yaourt 安装就是社区打包的软件了.<br>\\n软件来源各种各样,有的是 Google code 上的,有的是 GitHub 上的,有的就是 sourceforge 上的了.<br>\\n但是在中国的大环境下不能保证上面网站的正常访问 QAQ Google 的话有 hosts 的情况下基本上是\\n把 http 修改成 https 就可以下载了,其余两个就只能代理进行下载软件并安装了.</p>\\n<h2 id=\\"代理\\" tabindex=\\"-1\\">代理 <a class=\\"header-anchor\\" href=\\"#代理\\" aria-label=\\"Permalink to &quot;代理&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先科学上网的话就需要代理,SSH 这样进行端口监听的比较不错.VPN 是全局代理就不用讲述了.\\n不过 VPN 也可以走路由表进行部分代理(不在本文讨论范围之内)SSH 的话在 Linux 下就是简单的一句 <code>ssh -NfD 127.0.0.1:7070 user@server</code><br>\\n因为 SSH 不是 HTTP 代理,所以需要转发,如果是纯 HTTP 代理的话直接配置环境变量即可.\\n前面写的是本机代理的端口,后面是服务器的用户名和服务器 IP 地址.</p>\\n<h2 id=\\"转发\\" tabindex=\\"-1\\">转发 <a class=\\"header-anchor\\" href=\\"#转发\\" aria-label=\\"Permalink to &quot;转发&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>SSH 是 SOCKET5 代理,但是下载的话基本上就是 HTTP 代理怎么转发呢? 这里就需要一个软件叫做<a href=\\"https://wiki.archlinux.org/index.php/Privoxy\\" target=\\"_blank\\" rel=\\"noreferrer\\">Privoxy</a>\\nPrivoxy 可以把 SOCKET5 转 HTTP 代理,\\n首先安装它 <code>sudo pacman -S privoxy</code> 然后进行配置 <code>sudo vim /etc/privoxy/config</code>在配置文件里面添加 <code>forward-socks5 / 127.0.0.1:7070 .</code>\\n注意后面有个点,容易忽略. 这个是转入的 SOCKET5 代理,指的是 SSH 的代理监听的端口号.\\n配置文件里面有句话是 <code>listen-address 127.0.0.1:8118</code> 这个是转发出去的 HTTP 代理的端口号.\\n这样写好之后, 启动服务 <code>sudo systemctl start privoxy.service</code></p>\\n<h2 id=\\"配置环境变量\\" tabindex=\\"-1\\">配置环境变量 <a class=\\"header-anchor\\" href=\\"#配置环境变量\\" aria-label=\\"Permalink to &quot;配置环境变量&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>转发实现之后就可以应用在终端里面了,\\n在终端里面输入</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#24292E\\"> https_proxy</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">127.0.0.1:8118</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#24292E\\"> http_proxy</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">127.0.0.1:8118</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>这样就完成代理的设置了.</p>\\n"}]},"relativePath":"tags/proxy/index.md","filePath":"tags/[slug].md"}'),o={name:"tags/proxy/index.md"};function n(r,t,p,l,i,c){return a(),s("div")}const u=e(o,[["render",n]]);export{h as __pageData,u as default};
